#include "multi_head_attention_custom_tiling.h"
#include "register/op_def_registry.h"
#include <cmath>

namespace optiling {

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    MultiHeadAttentionCustomTilingData tiling;

    // 期望输入 q 的形状为 [B, H, S, D]
    const gert::Shape* q_shape = context->GetInputShape(0);
    auto origin = q_shape->GetOriginShape();

    uint32_t B = static_cast<uint32_t>(origin.GetDim(0));
    uint32_t H = static_cast<uint32_t>(origin.GetDim(1));
    uint32_t S = static_cast<uint32_t>(origin.GetDim(2));
    uint32_t D = static_cast<uint32_t>(origin.GetDim(3));

    tiling.set_B(B);
    tiling.set_H(H);
    tiling.set_S(S);
    tiling.set_D(D);
    float scale = 1.0f / std::sqrt(static_cast<float>(D));
    tiling.set_scale(scale);

    // 将 blockDim 设为 B * H（每个 block 负责一个 batch-head）
    uint32_t block_dim = B * H;
    if (block_dim == 0) {
        block_dim = 1;
    }
    context->SetBlockDim(block_dim);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());
    size_t* currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}

} // namespace optiling

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    const gert::Shape* q_shape = context->GetInputShape(0);
    gert::Shape* o_shape = context->GetOutputShape(0);
    *o_shape = *q_shape; // 输出形状与 q 相同 [B, H, S, D]
    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    const auto inputDataType = context->GetInputDataType(0);
    context->SetOutputDataType(0, inputDataType);
    return ge::GRAPH_SUCCESS;
}
